/**
 * eval/score.js
 * 
 * Standalone Node.js Scoring & Benchmarking Script.
 * Reads evaluation results generated by the eval runner alongside ground-truth labels from test-set.json.
 * Computes confusion matrices (TP, FP, TN, FN), Precision, Recall, F1 score, Accuracy,
 * and average/median latency, outputting a side-by-side comparison table.
 */

const fs = require('fs');
const path = require('path');

// File paths
const TEST_SET_PATH = path.join(__dirname, 'test-set.json');
const REGEX_ONLY_PATH = path.join(__dirname, 'results-regex-only.json');
const HYBRID_LLM_PATH = path.join(__dirname, 'results-regex-llm.json');

// Import regex & policy engines for standalone Node evaluation if result files aren't pre-generated
const { runRegexChecks } = require('../detectors/regex.js');
const { calculateRiskScore } = require('../engine/risk-score.js');
const { evaluatePolicy } = require('../engine/policy.js');

function loadJSON(filePath) {
  if (!fs.existsSync(filePath)) return null;
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (e) {
    return null;
  }
}

/**
 * Computes classification metrics from evaluation results.
 * @param {Array} results 
 * @returns {Object}
 */
function calculateMetrics(results) {
  let tp = 0; // Sensitive prompt correctly flagged (block or redact)
  let fp = 0; // Benign prompt wrongly flagged (block or redact)
  let tn = 0; // Benign prompt correctly allowed
  let fn = 0; // Sensitive prompt missed (allow)

  const latencies = [];

  for (const item of results) {
    const isTruthSensitive = item.ground_truth_sensitive !== undefined ? item.ground_truth_sensitive : item.is_sensitive;
    const isPredictedFlagged = item.predicted_action === 'block' || item.predicted_action === 'redact';

    if (isTruthSensitive && isPredictedFlagged) {
      tp++;
    } else if (!isTruthSensitive && isPredictedFlagged) {
      fp++;
    } else if (!isTruthSensitive && !isPredictedFlagged) {
      tn++;
    } else if (isTruthSensitive && !isPredictedFlagged) {
      fn++;
    }

    if (typeof item.llm_latency_ms === 'number' && item.llm_latency_ms > 0) {
      latencies.push(item.llm_latency_ms);
    }
  }

  const precision = (tp + fp) > 0 ? (tp / (tp + fp)) : 0;
  const recall = (tp + fn) > 0 ? (tp / (tp + fn)) : 0;
  const f1 = (precision + recall) > 0 ? (2 * precision * recall / (precision + recall)) : 0;
  const accuracy = (tp + tn + fp + fn) > 0 ? ((tp + tn) / (tp + tn + fp + fn)) : 0;

  latencies.sort((a, b) => a - b);
  const avgLatency = latencies.length > 0 ? (latencies.reduce((sum, val) => sum + val, 0) / latencies.length) : 0;
  const medianLatency = latencies.length > 0 ? latencies[Math.floor(latencies.length / 2)] : 0;

  return {
    total: results.length,
    tp, fp, tn, fn,
    precision: (precision * 100).toFixed(2) + '%',
    recall: (recall * 100).toFixed(2) + '%',
    f1: (f1 * 100).toFixed(2) + '%',
    accuracy: (accuracy * 100).toFixed(2) + '%',
    avgLatencyMs: avgLatency.toFixed(1) + ' ms',
    medianLatencyMs: medianLatency.toFixed(1) + ' ms'
  };
}

/**
 * Runs standalone Node.js Regex-only evaluation directly over test-set.json if results file missing.
 */
function runStandaloneNodeRegexEval(testSet) {
  const results = [];
  for (const item of testSet) {
    const regexMatches = runRegexChecks(item.text);
    const riskAnalysis = calculateRiskScore({
      regexMatches,
      llmResult: { sensitive: false, category: null, confidence: 0, skipped: true },
      userRole: 'engineering',
      destinationDomain: 'chatgpt.com'
    });
    const policyResult = evaluatePolicy({
      regexMatches,
      llmResult: { sensitive: false, category: null, confidence: 0, skipped: true },
      riskAnalysis,
      customPolicyConfig: { blockThreshold: 75, redactThreshold: 45 }
    });

    results.push({
      id: item.id,
      ground_truth_sensitive: item.is_sensitive,
      predicted_action: policyResult.action,
      riskScore: policyResult.riskScore,
      llm_latency_ms: 0
    });
  }
  return results;
}

function main() {
  console.log('===============================================================');
  console.log('       AI GOVERNANCE LAYER — RESEARCH EVALUATION SCORER        ');
  console.log('===============================================================\n');

  const testSet = loadJSON(TEST_SET_PATH);
  if (!testSet) {
    console.error('Error: Could not load test-set.json from', TEST_SET_PATH);
    process.exit(1);
  }

  console.log(`Loaded Ground-Truth Test Dataset: ${testSet.length} synthetic prompts`);

  // Load results from JSON files
  let regexResults = loadJSON(REGEX_ONLY_PATH);
  let hybridResults = loadJSON(HYBRID_LLM_PATH);

  if (!regexResults) {
    console.log('[Note] results-regex-only.json not found in eval/ folder. Running standalone Node.js Regex evaluation...');
    regexResults = runStandaloneNodeRegexEval(testSet);
  }

  const regexMetrics = calculateMetrics(regexResults);
  const hybridMetrics = hybridResults ? calculateMetrics(hybridResults) : null;

  console.log('\n---------------------------------------------------------------');
  console.log('              ABLATION COMPARISON RESULTS TABLE                ');
  console.log('---------------------------------------------------------------');
  console.log(pad('Metric / Statistic', 24) + ' | ' + pad('Pass 1: Regex Only', 20) + ' | ' + pad('Pass 2: Hybrid (Regex+LLM)', 22));
  console.log('----------------------------------------------------------------------------------');
  console.log(pad('Total Evaluated Prompts', 24) + ' | ' + pad(String(regexMetrics.total), 20) + ' | ' + pad(hybridMetrics ? String(hybridMetrics.total) : 'Pending in Browser', 22));
  console.log(pad('True Positives (TP)', 24) + ' | ' + pad(String(regexMetrics.tp), 20) + ' | ' + pad(hybridMetrics ? String(hybridMetrics.tp) : 'N/A', 22));
  console.log(pad('False Positives (FP)', 24) + ' | ' + pad(String(regexMetrics.fp), 20) + ' | ' + pad(hybridMetrics ? String(hybridMetrics.fp) : 'N/A', 22));
  console.log(pad('True Negatives (TN)', 24) + ' | ' + pad(String(regexMetrics.tn), 20) + ' | ' + pad(hybridMetrics ? String(hybridMetrics.tn) : 'N/A', 22));
  console.log(pad('False Negatives (FN)', 24) + ' | ' + pad(String(regexMetrics.fn), 20) + ' | ' + pad(hybridMetrics ? String(hybridMetrics.fn) : 'N/A', 22));
  console.log('----------------------------------------------------------------------------------');
  console.log(pad('PRECISION', 24) + ' | ' + pad(regexMetrics.precision, 20) + ' | ' + pad(hybridMetrics ? hybridMetrics.precision : 'N/A', 22));
  console.log(pad('RECALL', 24) + ' | ' + pad(regexMetrics.recall, 20) + ' | ' + pad(hybridMetrics ? hybridMetrics.recall : 'N/A', 22));
  console.log(pad('F1 SCORE', 24) + ' | ' + pad(regexMetrics.f1, 20) + ' | ' + pad(hybridMetrics ? hybridMetrics.f1 : 'N/A', 22));
  console.log(pad('ACCURACY', 24) + ' | ' + pad(regexMetrics.accuracy, 20) + ' | ' + pad(hybridMetrics ? hybridMetrics.accuracy : 'N/A', 22));
  console.log('----------------------------------------------------------------------------------');
  console.log(pad('Average LLM Latency', 24) + ' | ' + pad('0.0 ms (N/A)', 20) + ' | ' + pad(hybridMetrics ? hybridMetrics.avgLatencyMs : 'N/A', 22));
  console.log(pad('Median LLM Latency', 24) + ' | ' + pad('0.0 ms (N/A)', 20) + ' | ' + pad(hybridMetrics ? hybridMetrics.medianLatencyMs : 'N/A', 22));
  console.log('----------------------------------------------------------------------------------\n');

  if (!hybridResults) {
    console.log('[Tip] To populate the Pass 2: Hybrid column with Gemini Nano metrics:');
    console.log(' 1. Open Chrome and click "Launch Evaluation Runner Page" in the extension popup.');
    console.log(' 2. Click "Run Pass 2: Hybrid (Regex + On-Device Gemini Nano)".');
    console.log(' 3. Save the downloaded results-regex-llm.json into the eval/ directory.');
    console.log(' 4. Re-run `node eval/score.js`.\n');
  }
}

function pad(str, length) {
  return (str + ' '.repeat(length)).slice(0, length);
}

main();
